set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import dns from 'node:dns/promises';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-alt25-20261122',r={at:new Date().toISOString(),dns:[],scripts:[],restErrors:[],biggo:[]};const configs=[{name:'system',resolver:dns},{name:'cloudflare',resolver:new dns.Resolver({timeout:1500,tries:1})},{name:'google',resolver:new dns.Resolver({timeout:1500,tries:1})}];configs[1].resolver.setServers(['1.1.1.1']);configs[2].resolver.setServers(['8.8.8.8']);await Promise.all(configs.map(async c=>{for(const type of ['A','NS']){const o={resolver:c.name,type};try{o.records=await c.resolver.resolve('2saigon.vn',type);}catch(e){o.error=e.code;}r.dns.push(o);}}));
const follow=JSON.parse(fs.readFileSync(root+'/followup.json'));for(const p of follow.checks.filter(p=>p.kind==='script'&&!p.error&&p.file)){const s=gunzipSync(fs.readFileSync(p.file)).toString();r.scripts.push({site:p.site,url:p.url,ajax:s.match(/.{0,100}(?:ajaxurl|ajax_url|\.ajax\(|\burl\s*:|\bfetch\(|\.get\().{0,200}/g)?.slice(0,12),phpPaths:[...new Set([...s.matchAll(/["'`]([^"'`\s]{0,120}\.php(?:\?[^"'`\s]{0,100})?)["'`]/g)].map(m=>m[1]))].slice(0,12)});}
const routes=JSON.parse(fs.readFileSync(root+'/routes.json'));for(const p of routes.sites.find(s=>s.site==='gialaitv.vn').jobs.filter(p=>p.statusCode===503&&p.file).slice(0,2)){const $=ch.load(gunzipSync(fs.readFileSync(p.file)).toString());r.restErrors.push({url:p.url,message:$('body').text().replace(/\s+/g,' ').slice(0,1200)});}
const assets=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-remaining28-20261122/biggo-assets.json'));for(const p of assets.checks.filter(p=>p.url.includes('/app/news/'))){const s=gunzipSync(fs.readFileSync(p.file)).toString();r.biggo.push({url:p.url,readFetches:s.match(/.{0,180}(?:news_id|\/news\/|getNewsDetail|view-attest).{0,220}/g)?.filter(s=>/\.wi|fetch\(|api\.|concat/.test(s)).slice(0,15)});}
fs.writeFileSync(root+'/extra-inspection.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-alt25-20261122/extra-inspection.json "$upload_dir/.qc-alt25-extra-inspection.json"
